parameters.jsCode:
const rows = items.map(i => i.json);
const html = rows.map(r => {
  const who = r.role === 'user' ? 'Visitante' : 'Asistente';
  return `<p><strong>${who}:</strong> ${r.content}</p>`;
}).join('\n');

return [{ json: { summaryHtml: html } }];

// ============================================================
// SAFETY NET - Verificación de ejecución de enviar_mail
// ============================================================
const agentOutput = $input.first().json;
const outputText = agentOutput.output || '';
const steps = agentOutput.intermediateSteps || [];

// ============================================================
// ¿Se ejecutó la tool enviar_mail en algún step intermedio?
// ============================================================
const mailStep = steps.find(s =>
  s.action?.tool?.toLowerCase().startsWith('enviar_mail')
);
const mailCalled = !!mailStep;

return [{
  json: {
    mailCalled,
    output: outputText,
    intermediateSteps: steps
  }
}];

